import random
from collections import Counter

def solve_optimal(s):
    counts = Counter(s)
    for i, ch in enumerate(s):
        if counts[ch] == 1:
            return i
    return -1

def solve_brute(s):
    for i in range(len(s)):
        if all(s[j] != s[i] for j in range(len(s)) if j != i):
            return i
    return -1

def gen(rng, size):
    low, high = {"tiny": (0, 4), "small": (0, 12), "large": (30, 100)}[size]
    n = rng.randint(low, high)
    alphabet = "abcde" if size != "large" else "abcdefghij"
    return ["".join(rng.choice(alphabet) for _ in range(n))]

def validate(args):
    s = args[0]
    return isinstance(s, str) and len(s) <= 10**5 and all("a" <= c <= "z" for c in s)
